// Convenient lookups
const memberByFlat = (f) => MEMBERS.find(m => m.flat === f);

// Current "logged in" member: Saurabh Sharma (Flat 133)
const CURRENT_MEMBER = memberByFlat(133);

// Managing Committee derived from MEMBERS where committee field is set.
const COMMITTEE = MEMBERS.filter(m => m.committee).map(m => ({
  name: m.name,
  role: m.committee,
  flat: `Flat ${m.flat}`,
  term: "2024–2026",
  email: m.email,
  phone: m.phone,
}));

// Per-member completeness — counts which of the optional fields are present.
const REQUIRED_FIELDS = [
  { key: "email",         label: "Email" },
  { key: "phone",         label: "Phone" },
  { key: "membership",    label: "Membership No." },
  { key: "ownership",     label: "Occupancy" },
  { key: "parking",       label: "Parking" },
];
function memberCompleteness(m) {
  const missing = REQUIRED_FIELDS.filter(f => !m[f.key]).map(f => f.key);
  return {
    pct: Math.round(((REQUIRED_FIELDS.length - missing.length) / REQUIRED_FIELDS.length) * 100),
    missing,
  };
}

// Aggregate completion stats
const DATA_COMPLETION = {
  total: MEMBERS.length,
  byField: REQUIRED_FIELDS.map(f => ({
    key: f.key,
    label: f.label,
    filled: MEMBERS.filter(m => m[f.key]).length,
    missing: MEMBERS.filter(m => !m[f.key]).length,
  })),
  loginEnabled: MEMBERS.filter(m => m.login === "Enabled").length,
  loginPending: MEMBERS.filter(m => m.login === "Pending").length,
  loginNotInvited: MEMBERS.filter(m => m.login === "Not invited").length,
  noEmail: MEMBERS.filter(m => !m.email && !m.deceased).length,
  deceased: MEMBERS.filter(m => m.deceased).length,
  fullProfiles: MEMBERS.filter(m => memberCompleteness(m).missing.length === 0).length,
};

